INSERT INTO `wp_ro_menu_items` VALUES (1,1,1,'Crispy Truffle Fries','Hand-cut golden fries tossed with black truffle oil, rosemary, and aged parmesan with garlic aioli dip.','https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=600&q=80',8.50,5.00,'veg','available',1,0,10,'2026-09-12 13:33:32'),(2,1,1,'Smoked Chicken Wings','Hickory smoked wings glazed in spicy habanero honey or smoky barbecue sauce.','https://images.unsplash.com/photo-1567620832903-9fc6debc209f?auto=format&fit=crop&w=600&q=80',12.00,5.00,'non_veg','available',1,0,15,'2026-09-12 13:33:32'),(3,2,2,'Flame-Grilled Ribeye Steak','300g Prime Angus beef ribeye, charred herb butter, roasted asparagus, and pepper sauce.','https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=600&q=80',28.00,5.00,'non_veg','available',1,0,20,'2026-09-12 13:33:32'),(4,2,2,'Charred Tandoori Chicken Tikka','Succulent boneless chicken marinated in hung curd, Kashmiri chili, and aromatic spices cooked over live coals.','https://images.unsplash.com/photo-1599488615731-7e5c2823ff28?auto=format&fit=crop&w=600&q=80',16.50,5.00,'non_veg','available',1,0,18,'2026-09-12 13:33:32'),(5,3,1,'Royal Dum Biriyani','Fragrant long-grain aged basmati rice layered with slow-cooked marinated chicken, saffron, mint, and fried onions.','https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=600&q=80',17.50,5.00,'non_veg','available',1,0,15,'2026-09-12 13:33:32'),(6,3,1,'Creamy Paneer Butter Masala','Cottage cheese cubes simmered in a velvety tomato gravy finished with butter, cream, and dried fenugreek.','https://images.unsplash.com/photo-1631452180519-c014fe946bc7?auto=format&fit=crop&w=600&q=80',14.00,5.00,'veg','available',0,0,12,'2026-09-12 13:33:32'),(7,4,3,'Fresh Mint & Lime Soda','Sparkling water infused with crushed garden mint, freshly squeezed lime, and organic cane syrup.','https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?auto=format&fit=crop&w=600&q=80',4.50,5.00,'beverage','available',1,0,5,'2026-09-12 13:33:32'),(8,4,3,'Iced Salted Caramel Cold Brew','16-hour slow-steeped Arabica coffee topped with artisanal sea salt caramel cold foam.','https://images.unsplash.com/photo-1517701550927-30cf4ba1dba5?auto=format&fit=crop&w=600&q=80',5.50,5.00,'beverage','available',0,0,5,'2026-09-12 13:33:32'),(9,5,4,'Molten Dark Chocolate Lava Cake','Warm Belgian dark chocolate cake with a rich flowing center, served with Madagascar vanilla bean gelato.','https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=600&q=80',7.50,5.00,'veg','available',1,0,12,'2026-09-12 13:33:32');
